-- ==========================================================
-- Little Horizons ERP - Datos de Prueba (Seed Data)
-- Minimo 30 registros por cada tabla principal
-- Motor: MySQL 8.0 o superior
-- NOTA: Este archivo es INDEPENDIENTE del esquema de tablas (database.sql).
-- ==========================================================

USE erp_little_horizons;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Grados Academicos
ON DUPLICATE KEY UPDATE nombre_grado=VALUES(nombre_grado);

-- 2. Categorias de Recursos
ON DUPLICATE KEY UPDATE descripcion=VALUES(descripcion);

-- 3. Conceptos de Pago
ON DUPLICATE KEY UPDATE monto_base=VALUES(monto_base);

-- 4. Profesores (30 registros)
ON DUPLICATE KEY UPDATE correo_electronico=VALUES(correo_electronico);

-- 5. Estudiantes (30 registros)
ON DUPLICATE KEY UPDATE primer_nombre=VALUES(primer_nombre);

-- 6. Acudientes (30 registros)
ON DUPLICATE KEY UPDATE telefono_principal=VALUES(telefono_principal);

-- 7. Vinculos Estudiante - Acudiente
ON DUPLICATE KEY UPDATE es_principal=VALUES(es_principal);

-- 8. Matriculas de Estudiantes (30 registros - 2024)
ON DUPLICATE KEY UPDATE estado_matricula=VALUES(estado_matricula);

-- 9. Materias por Grado (30 registros)
ON DUPLICATE KEY UPDATE nombre_materia=VALUES(nombre_materia);

-- 10. Asignaciones de Profesor (30 registros)
ON DUPLICATE KEY UPDATE seccion=VALUES(seccion);

-- 11. Inscripciones en Materias (30 registros)
ON DUPLICATE KEY UPDATE estado=VALUES(estado);

-- 12. Registros Academicos / Calificaciones (30 registros)
ON DUPLICATE KEY UPDATE valor_nota=VALUES(valor_nota);

-- 13. Asistencias Diarias (30 registros)
ON DUPLICATE KEY UPDATE estado_asistencia=VALUES(estado_asistencia);

-- 14. Catalogo de Clubes Extracurriculares (30 registros)
ON DUPLICATE KEY UPDATE capacidad_maxima=VALUES(capacidad_maxima);

-- 15. Membresias en Clubes (30 registros)
ON DUPLICATE KEY UPDATE estado_membresia=VALUES(estado_membresia);

-- 16. Eventos Institucionales (30 registros)
ON DUPLICATE KEY UPDATE lugar=VALUES(lugar);

-- 17. Participantes en Eventos (30 registros)
ON DUPLICATE KEY UPDATE posicion_obtenida=VALUES(posicion_obtenida);

-- 18. Pagos Registrados (30 registros)
ON DUPLICATE KEY UPDATE monto_pagado=VALUES(monto_pagado);

-- 19. Facturas Electronicas DIAN Simuladas (30 registros)
ON DUPLICATE KEY UPDATE cufe=VALUES(cufe);

-- 20. Inventario de Recursos (30 registros)
ON DUPLICATE KEY UPDATE nombre_recurso=VALUES(nombre_recurso);

-- 21. Prestamos de Recursos a Estudiantes (30 registros)
ON DUPLICATE KEY UPDATE estado_prestamo=VALUES(estado_prestamo);

-- 22. Prestamos de Recursos a Profesores (30 registros)
ON DUPLICATE KEY UPDATE estado_prestamo=VALUES(estado_prestamo);

SET FOREIGN_KEY_CHECKS = 1;
